def longest_word_in_dictionary(words):
    root = {'children': {}, 'is_end': False}

    for word in words:
        node = root
        for ch in word:
            node = node['children'].setdefault(ch, {'children': {}, 'is_end': False})
        node['is_end'] = True

    best = ['']

    def dfs(node, path):
        if len(path) > len(best[0]) or (len(path) == len(best[0]) and path < best[0]):
            best[0] = path
        for ch in sorted(node['children']):
            child = node['children'][ch]
            if child['is_end']:
                dfs(child, path + ch)

    dfs(root, '')
    return best[0]

